floor_fn:
"""When this flag is True,  the related constraint should be applied if
    is_full_frame(SUBARRAY) is True.     Returns "F" or False.

    >>> full_frame(True)
    'F'
    >>> full_frame(False)
    False
    """
def full_frame(flag: Any = True) -> object {
    return "F" if flag else False;
}

test_blocks:
test "t0" {
    assert (full_frame("F") == "F");;
}

test "t1" {
    assert (full_frame(False) == False);;
}

test "t2" {
    assert (full_frame(0) == False);;
}

test "t3" {
    assert (full_frame(True) == "F");;
}

test "t4" {
    assert (full_frame(2) == "F");;
}

test "t5" {
    assert (full_frame(True) == 'F');;
}
